sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-ft {
  background: var(--surface);
  border-top: 1px solid var(--line);
  margin-top: 40px;
}
.wrm-ft-inner {
  max-width: 1400px; margin: 0 auto;
  padding: 24px 20px;
  display: flex; align-items: flex-start; gap: 28px; flex-wrap: wrap;
}

.wrm-ft-brand { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; }
.wrm-ft-brand .mark {
  width: 18px; height: 18px; background: var(--clay);
  border-radius: var(--r-pill); flex: none;
}
.wrm-ft-brand .word { font-size: 14px; font-weight: 500; color: var(--ink); }
.wrm-ft-brand .tag { font-size: 12px; color: var(--ink-3); }

.wrm-ft-links { display: flex; gap: 20px; flex-wrap: wrap; margin-left: auto; }
.wrm-ft-links a { font-size: 12px; color: var(--ink-2); text-decoration: none; }
.wrm-ft-links a:hover { color: var(--clay); text-decoration: none; }

.wrm-ft-legal { font-size: 11px; color: var(--ink-3); width: 100%; }
